// --- PARAMETRI ---
float scale = 50.0; // Densità degli anelli (più alto = più cerchi)
vec2 center = vec2(0.5, 0.5); // Center of the circles (0.5, 0.5 is the center of the texture)

// --- LOGIC ---
// 1. Computes the distance of the current pixel (u, v) from the center
float dist = distance(vec2(u, v), center);

// 2. Creates the sine wave based on the distance
// We multiply by 'scale' to raise the frequency
float val = sin(dist * scale);

// 3. We map the result from -1..1 to 0..1 for the mix
float tit = (val + 1.0) * 0.5;

// 4. Mix finale
return mix(u_col1, u_col2, tit);

