// --- POST-PROCESSING 2D: MONITOR CRT ---

// gl_FragCoord.xy gives us the physical pixels of the screen, regardless
// of the rotation of the camera or of the 3D object!
// We divide by an indicative value to normalize the coordinates.
vec2 screenUV = gl_FragCoord.xy / 800.0;

// 1. SCANLINES (horizontal lines)
// We use slider 'A' to adjust the density of the lines on the fly (e.g. range 1-5)
float scanlineDensity = 1500.0;   // edit this to change the scanline density
float scanline = sin(screenUV.y * scanlineDensity) * 0.1 + 0.9;

// 2. FLICKER (time-based flicker)
// Slider 'B' sets the intensity of the flicker
float flicker = 1.0 - (0.05 * sin(t * 50.0));   // raise 0.05 for a stronger flicker

// 3. CHROMATIC ABERRATION ON THE PIXELS OF THE OBJECT
// Instead of using a solid color, we offset u_col1 to create the separated RGB effect
vec3 col;
col.r = u_col1.r * 1.1; 
col.g = u_col1.g * 0.9;
col.b = u_col1.b * 1.5; // We raise the blue to give a hi-tech look

// 4. ROLLING BANDS (vertical interference)
// A dark band that scrolls from top to bottom
float roll = fract(screenUV.y * 0.5 - t * 0.2);
float distortionBand = smoothstep(0.4, 0.5, roll) - smoothstep(0.5, 0.6, roll);

// We lower the brightness where the band passes
col *= 1.0 - (distortionBand * 0.3);

// 5. APPLICAZIONE DEI FILTRI 2D
vec3 finalColor = col * scanline * flicker;

return finalColor;
